<?php require_once __DIR__.'/../includes/tutor_auth_check.php';require_once __DIR__.'/../config/db.php';$stats=['students'=>0,'upcoming'=>0,'pending'=>0,'rating'=>0];try{$p=db();$q=$p->prepare('SELECT id,rating FROM tutors WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$t=$q->fetch();if($t){$id=$t['id'];$stats['rating']=$t['rating'];foreach(['students'=>"COUNT(DISTINCT student_id)",'upcoming'=>"COUNT(*)","pending"=>"COUNT(*)"] as $key=>$select){$condition=$key==='upcoming'?"status='accepted' AND booking_date>=CURDATE()":($key==='pending'?"status='pending'":'1');$q=$p->prepare("SELECT $select FROM bookings WHERE tutor_id=? AND $condition");$q->execute([$id]);$stats[$key]=$q->fetchColumn();}}}catch(Throwable $e){}$pageTitle='Tutor dashboard';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?><main class="section-soft py-5"><div class="container"><h1 class="h2">Tutor dashboard</h1><div class="row g-3 mt-2"><?php foreach(['students'=>'Total students','upcoming'=>'Upcoming sessions','pending'=>'Pending requests','rating'=>'Average rating'] as $key=>$label):?><div class="col-6 col-lg-3"><div class="profile-section text-center"><strong class="display-6"><?=e((string)$stats[$key])?></strong><div class="text-secondary small"><?=$label?></div></div></div><?php endforeach;?></div><div class="mt-4"><a class="btn btn-brand me-2" href="requests.php">Manage requests</a><a class="btn btn-outline-brand" href="../schedule.php">Schedule</a></div></div></main><?php require __DIR__.'/../includes/footer.php';?>
